 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 * 第三方字体、图片、图标和代码继续遵守各自原许可证。
 */
/* SOURCE: src/kernel/scrollbars.css */
/* 隐藏滚动条外观，但保留滚轮、触摸、键盘与内容滚动。 */
::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

/* SOURCE: src/core-layout.css */
/*
 * 春来 · SillyTavern 1.14.0 原生布局约束
 * 保留 #sheld、抽屉、#send_form 与 .mes 的官方 display/position/滚动关系。
 */

#chat .mes:not([is_system="true"]) {
    width: min(100%, 760px);
    margin-inline: auto;
}

#chat .mes:not([is_system="true"]) > .mes_block {
    flex: 1 1 0;
    width: auto;
    min-width: 0;
    margin-inline: 0;
}

/* 主题字段会给 body 添加 hideChatAvatars；仅清除空头像列的几何占位。 */
body.hideChatAvatars #chat .mes:not([is_system="true"]) > .mesAvatarWrapper {
    flex: 0 0 0;
    width: 0;
    min-width: 0;
    margin: 0;
    padding: 0;
}

/* SOURCE: src/visual.css */
/*
 * 春来 · 水际翡翠与纸本编辑主题
 * 目标：1.14.0；兼容参考：1.18.0。
 */

@font-face {
    font-family: "Source Han Serif SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Cormorant SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/cormorant-sc/CormorantSC-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --cl-deep: #3b584b;
    --cl-mid: #52796c;
    --cl-mist: #819b85;
    --cl-olive: #c3c0aa;
    --cl-paper: #efeada;
    --cl-paper-strong: #f8f5eb;
    --cl-paper-soft: #f3efe3;
    --cl-ink: #283d36;
    --cl-text: #3f4b45;
    --cl-muted: #70786f;
    --cl-danger: #9b625d;
    --cl-warning: #9a7a43;
    --cl-success: #52796c;
    --cl-border: rgba(82, 121, 108, 0.46);
    --cl-border-soft: rgba(82, 121, 108, 0.22);
    --cl-rule: rgba(59, 88, 75, 0.32);
    --cl-shadow: 0 12px 34px rgba(59, 88, 75, 0.12);
    --cl-shadow-soft: 0 4px 14px rgba(59, 88, 75, 0.09);
    --cl-glass-chat: rgba(248, 245, 235, 0.72);
    --cl-glass-chrome: rgba(248, 245, 235, 0.78);
    --cl-glass-input: rgba(248, 245, 235, 0.82);
    --cl-glass-blur: 12px;
    --cl-glass-saturation: 108%;
    --cl-quote-bg: rgba(82, 121, 108, 0.12);
    --cl-quote-text: #405249;
    --cl-quote-border: rgba(82, 121, 108, 0.16);
    --cl-quote-inline-bg: rgba(82, 121, 108, 0.14);
    --cl-quote-inline-text: #405249;
    --cl-radius-sm: 4px;
    --cl-radius-md: 7px;
    --cl-radius-lg: 10px;
    --cl-font-serif: "Source Han Serif SC", "Noto Serif CJK SC", "Songti SC", SimSun, serif;
    --cl-font-label: "Cormorant SC", "Source Han Serif SC", Georgia, serif;
    --cl-font-ui: var(--cl-font-serif);
    --cl-font-mono: "Cascadia Mono", "JetBrains Mono", Consolas, monospace;
    --mainFontFamily: var(--cl-font-serif);
    --cl-botanical-paper: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/e98c6a88f7dc60cdd149e863cd325e4bfd069df8/assets/chunlai/chunlai-botanical-paper.png");
}

body {
    color: var(--cl-text);
    background-color: var(--cl-paper);
    background-image:
        linear-gradient(rgba(239, 234, 218, 0.18), rgba(239, 234, 218, 0.18)),
        var(--cl-botanical-paper);
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
    font-family: var(--cl-font-serif);
}

:is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu) :focus-visible {
    outline: 2px solid var(--cl-deep);
    outline-offset: 2px;
}

::selection {
    color: var(--cl-ink);
    background: rgba(129, 155, 133, 0.42);
}

/* SOURCE: src/windows/chat.css */
/* ================================================================
   W01 页面背景与无头像主聊天
   ================================================================ */
#sheld {
    border-inline: 1px solid var(--cl-border-soft);
    box-shadow: 0 0 40px rgba(59, 88, 75, 0.10);
}

#chat {
    color: var(--cl-text);
    border-inline: 1px solid rgba(59, 88, 75, 0.14);
    background-color: var(--cl-glass-chat);
    background-image:
        linear-gradient(rgba(59, 88, 75, 0.018) 1px, transparent 1px),
        linear-gradient(90deg, rgba(59, 88, 75, 0.014) 1px, transparent 1px);
    background-position: center top, center top;
    background-repeat: repeat, repeat;
    background-size: 28px 28px, 28px 28px;
    -webkit-backdrop-filter: blur(var(--cl-glass-blur)) saturate(var(--cl-glass-saturation));
    backdrop-filter: blur(var(--cl-glass-blur)) saturate(var(--cl-glass-saturation));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.42);
    text-shadow: none;
}

#chat .mes:not([is_system="true"]) > .mes_block::before {
    content: "春 来 · CHUN LAI";
    display: block;
    box-sizing: border-box;
    width: 100%;
    height: clamp(138px, 17vw, 176px);
    margin: 0;
    padding: 16px 18px 0;
    color: var(--cl-deep);
    border-block: 1px solid var(--cl-rule);
    background:
        linear-gradient(to bottom, rgba(248, 245, 235, 0.99) 0 48px, rgba(248, 245, 235, 0.06) 48px 100%),
        var(--cl-botanical-paper) center 34% / cover no-repeat,
        var(--cl-paper-strong);
    box-shadow: inset 0 -1px 0 rgba(248, 245, 235, 0.72);
    font-family: var(--cl-font-label);
    font-size: calc(var(--mainFontSize, 15px) * 0.80);
    font-weight: 400;
    line-height: 1.4;
    letter-spacing: 0.18em;
    text-align: center;
    white-space: nowrap;
    pointer-events: none;
}

#chat .mes:not([is_system="true"]) {
    position: relative;
    margin-block: 12px 18px;
    padding: 0 clamp(22px, 4vw, 46px);
    color: var(--cl-text);
    border: 0;
    background: transparent;
    box-shadow: none;
}

#chat .mes:not([is_system="true"])[mesid]::after {
    content: "#" attr(mesid);
    position: absolute;
    top: 16px;
    left: calc(clamp(22px, 4vw, 46px) + 18px);
    color: var(--cl-deep);
    font-family: var(--cl-font-label);
    font-size: calc(var(--mainFontSize, 15px) * 0.80);
    font-weight: 400;
    line-height: 1.4;
    letter-spacing: 0.10em;
    pointer-events: none;
}

#chat .mes[is_user="true"] {
    padding-top: 0;
    padding-bottom: 0;
}

#chat .mes[is_user="false"] {
    padding-top: 0;
    padding-bottom: 0;
}

#chat .mes:not([is_system="true"]) > .mes_block {
    color: var(--cl-text);
    border-bottom: 1px solid var(--cl-border-soft);
    background-color: rgba(248, 245, 235, 0.965);
    box-shadow: 0 8px 20px rgba(59, 88, 75, 0.07);
    overflow-x: hidden;
}

#chat .ch_name {
    min-height: 0;
    margin: 0;
    padding: 8px 14px 7px;
    color: var(--cl-deep);
    font-family: var(--cl-font-label);
    border: 0;
    border-bottom: 1px solid rgba(82, 121, 108, 0.22);
}

#chat .name_text {
    color: var(--cl-deep);
    font-family: var(--cl-font-label);
    font-weight: 400;
    letter-spacing: 0.10em;
}

#chat .timestamp {
    color: var(--cl-muted);
    font-family: var(--cl-font-label);
    font-size: 0.76em;
    letter-spacing: 0.08em;
}

#chat :is(.mes_text, .mes_reasoning) {
    color: var(--cl-text);
    font-family: var(--cl-font-serif);
    font-size: var(--mainFontSize, 15px);
    font-weight: 400;
    line-height: 1.88;
    letter-spacing: 0.025em;
}

#chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning) {
    max-width: 680px;
    margin-inline: auto;
    padding: 13px 16px 20px;
    color: var(--cl-ink);
    background: transparent;
    font-size: 0.94em;
    line-height: 1.76;
}

#chat .mes[is_user="false"] :is(.mes_text, .mes_reasoning) {
    max-width: 680px;
    min-height: 0;
    height: auto;
    margin-inline: auto;
    padding: 15px 16px 28px;
    background: transparent;
}

#chat :is(.mes_text, .mes_reasoning) > p {
    margin: 0 0 0.92em;
}

#chat :is(.mes_text, .mes_reasoning) > p:last-child {
    margin-bottom: 0;
}

#chat .mes_reasoning_header {
    color: var(--cl-deep);
    border: 1px solid var(--cl-border-soft);
    border-radius: var(--cl-radius-sm);
    background-color: rgba(239, 234, 218, 0.94);
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_header:hover,
#chat .mes_reasoning_details[open] .mes_reasoning_header {
    color: var(--cl-ink);
    border-color: var(--cl-border);
    background-color: rgba(195, 192, 170, 0.40);
}

#chat .mes_reasoning_arrow {
    color: var(--cl-deep);
    opacity: 1;
    filter: none;
}

#chat :is(.mes_text, .mes_reasoning) hr {
    height: 1px;
    margin: 1.4em auto;
    border: 0;
    background: linear-gradient(90deg, transparent, var(--cl-mid), transparent);
}

#chat :is(.mes_text, .mes_reasoning) pre {
    color: var(--cl-ink);
    border: 1px solid var(--cl-border);
    border-radius: var(--cl-radius-sm);
    background: rgba(239, 234, 218, 0.78);
    box-shadow: inset 3px 0 0 var(--cl-mid);
}

#chat :is(.mes_text, .mes_reasoning) :is(pre, code) {
    font-family: var(--cl-font-mono);
}

#chat .mes_buttons,
#chat .mes_edit_buttons,
#chat .mes_reasoning_actions,
#chat .mes_button,
#chat .extraMesButtons > div,
#chat .mes_edit_buttons .menu_button,
#chat .mes_reasoning_actions .edit_button {
    color: var(--cl-mid);
    opacity: 0.86;
    filter: none;
    text-shadow: none;
}

#chat :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button):hover {
    color: var(--cl-deep);
    opacity: 1;
    filter: none;
}

#chat .mes_edit_buttons .menu_button {
    color: var(--cl-deep);
    border: 1px solid var(--cl-border);
    background-color: rgba(248, 245, 235, 0.96);
    box-shadow: none;
}

#chat .mes_edit_done.menu_button {
    color: #fff;
    border-color: var(--cl-deep);
    background-color: var(--cl-deep);
}

#chat .mes_edit_cancel.menu_button {
    color: #fff;
    border-color: var(--cl-danger);
    background-color: var(--cl-danger);
}

#chat :is(.reasoning_edit_textarea, .edit_textarea) {
    color: var(--cl-ink);
    border: 1px solid var(--cl-border);
    background-color: rgba(248, 245, 235, 0.98);
    box-shadow: inset 3px 0 0 var(--cl-mist);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#chat .mes[is_system="true"] {
    width: min(88%, 780px);
    margin: 8px auto;
    color: var(--cl-muted);
    border: 1px dashed var(--cl-border);
    border-radius: var(--cl-radius-md);
    background: rgba(248, 245, 235, 0.90);
}

/* SOURCE: src/full-text.css */
/* ================================================================
   正文语义排版：绿色行内引用与加深引用块
   ================================================================ */
#chat :is(.mes_text, .mes_reasoning) :is(q, .quote) {
    padding: 0.08em 0.42em;
    color: var(--cl-quote-inline-text);
    border-radius: var(--cl-radius-sm);
    background-color: var(--cl-quote-inline-bg);
    font-family: var(--cl-font-serif);
    font-style: normal;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
    margin: 0.9em 0;
    padding: 11px 16px;
    color: var(--cl-quote-text);
    border: 1px solid var(--cl-quote-border);
    border-left: 4px solid rgba(82, 121, 108, 0.24);
    border-radius: 0 var(--cl-radius-sm) var(--cl-radius-sm) 0;
    background-color: var(--cl-quote-bg);
    box-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) blockquote :is(p, q, .quote) {
    color: inherit;
}

/* SOURCE: src/windows/topbar.css */
/* ================================================================
   W02 顶栏与九个原生含义入口键
   ================================================================ */
#top-bar {
    color: var(--cl-deep);
    border-bottom: 1px solid var(--cl-rule);
    border-radius: 0;
    background-color: var(--cl-paper-strong);
    box-shadow: 0 5px 18px rgba(59, 88, 75, 0.08);
    text-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable) {
    position: relative;
    color: var(--cl-mid);
    border: 0;
    border-radius: 0;
    background: transparent;
    text-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable)::after {
    content: "";
    position: absolute;
    right: 22%;
    bottom: 2px;
    left: 22%;
    height: 1px;
    background: transparent;
    pointer-events: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable):hover,
#top-settings-holder .openIcon {
    color: var(--cl-deep);
    background: transparent;
    filter: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable):hover::after,
#top-settings-holder .openIcon::after {
    background: var(--cl-mid);
}

#ai-config-button,
#sys-settings-button,
#advanced-formatting-button,
#WI-SP-button,
#user-settings-button,
#backgrounds-button,
#extensions-settings-button,
#persona-management-button,
#rightNavHolder {
    background-color: transparent;
}

/* SOURCE: src/windows/input.css */
/* ================================================================
   W03 输入区、菜单、魔法棒与纸飞机
   ================================================================ */
#send_form {
    position: relative;
    color: var(--cl-text);
    border: 1px solid var(--cl-border);
    border-radius: var(--cl-radius-lg);
    background-color: var(--cl-paper-soft);
    box-shadow: inset 0 0 0 3px rgba(195, 192, 170, 0.12), var(--cl-shadow-soft);
    text-shadow: none;
}

#send_form::before,
#send_form::after {
    content: "";
    position: absolute;
    width: 18px;
    height: 18px;
    pointer-events: none;
}

#send_form::before {
    top: 4px;
    left: 4px;
    border-top: 1px solid var(--cl-mid);
    border-left: 1px solid var(--cl-mid);
}

#send_form::after {
    right: 4px;
    bottom: 4px;
    border-right: 1px solid var(--cl-mid);
    border-bottom: 1px solid var(--cl-mid);
}

#send_textarea {
    margin: 0;
    padding: 11px 13px;
    color: var(--cl-ink);
    border-color: var(--cl-border-soft);
    border-radius: var(--cl-radius-md);
    background: rgba(239, 234, 218, 0.62);
    box-shadow: none;
    font-family: var(--cl-font-serif);
    line-height: 1.62;
    text-shadow: none;
}

#send_textarea::placeholder {
    color: rgba(63, 75, 69, 0.60);
}

#send_form:focus-within {
    border-color: var(--cl-deep);
}

#leftSendForm > div,
#rightSendForm > div {
    position: relative;
    color: var(--cl-mid);
    border: 0;
    border-radius: 0;
    background: transparent;
    text-shadow: none;
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    color: var(--cl-deep);
    background-color: transparent;
    filter: none;
}

#leftSendForm > div::after,
#rightSendForm > div::after {
    content: "";
    position: absolute;
    right: 18%;
    bottom: 2px;
    left: 18%;
    height: 1px;
    background: transparent;
    pointer-events: none;
}

#leftSendForm > div:hover::after,
#rightSendForm > div:hover::after,
#leftSendForm > div:focus-visible::after,
#rightSendForm > div:focus-visible::after {
    background: var(--cl-mid);
}

#options_button,
#extensionsMenuButton,
#send_but.fa-paper-plane {
    color: var(--cl-deep);
    border: 0;
    background: transparent;
}

#send_but.fa-paper-plane::before {
    color: currentColor;
    opacity: 1;
}

#send_form .mes_stop {
    color: var(--cl-danger);
    border-bottom: 1px solid var(--cl-danger);
    background-color: transparent;
}

#options,
#extensionsMenu {
    color: var(--cl-text);
    border: 1px solid var(--cl-border);
    border-radius: var(--cl-radius-md);
    background: rgba(248, 245, 235, 0.99);
    box-shadow: var(--cl-shadow);
    text-shadow: none;
}

/* SOURCE: src/windows/common.css */
/* ================================================================
   通用抽屉与表单视觉；不改官方抽屉几何、显示或滚动
   ================================================================ */
.drawer-content {
    color: var(--cl-text);
    border-color: var(--cl-border);
    background-color: rgba(248, 245, 235, 0.99);
    background-image:
        linear-gradient(90deg, rgba(129, 155, 133, 0.10), transparent 28%),
        linear-gradient(rgba(255, 255, 255, 0.12), rgba(239, 234, 218, 0.10));
    box-shadow: var(--cl-shadow);
    text-shadow: none;
}

:is(.drawer-content, .popup, #options, #extensionsMenu)
    :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select) {
    color: var(--cl-ink);
    border-color: var(--cl-border);
    background-color: rgba(248, 245, 235, 0.96);
    font-family: var(--cl-font-ui);
    box-shadow: inset 0 0 0 1px rgba(129, 155, 133, 0.07);
}

/* Chromium 原生列表会脱离抽屉绘制，需精确覆盖官方深色 option。 */
select option,
select optgroup,
select option:not(:checked) {
    color: #3f4b45 !important;
    background-color: #f8f5eb !important;
}

select option:checked {
    color: #283d36 !important;
    background-color: #d9dbc9 !important;
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(input[type="range"], input[type="checkbox"], input[type="radio"]) {
    accent-color: var(--cl-deep);
}

:is(.drawer-content, .popup, #options, #extensionsMenu)
    :is(input:not([type="range"]), textarea, select, button, .menu_button):disabled,
:is(.drawer-content, .popup, #options, #extensionsMenu) .disabled {
    color: #687169;
    background-color: rgba(224, 221, 204, 0.88);
    opacity: 0.82;
    filter: none;
    text-shadow: none;
}

.select2-container--default .select2-results__option {
    color: var(--cl-text);
    background-color: var(--cl-paper-strong);
}

.select2-container--default .select2-results__option--highlighted,
.select2-container--default .select2-results__option[aria-selected="true"] {
    color: var(--cl-ink);
    background-color: rgba(195, 192, 170, 0.58);
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button) {
    color: var(--cl-deep);
    border-color: var(--cl-border);
    border-radius: var(--cl-radius-sm);
    background-color: rgba(239, 234, 218, 0.88);
    text-shadow: none;
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button):hover {
    color: var(--cl-deep);
    border-color: var(--cl-deep);
    background-color: rgba(195, 192, 170, 0.40);
    filter: none;
}

.inline-drawer-header,
.standoutHeader {
    margin-block: 4px;
    padding: 7px 10px;
    color: var(--cl-deep);
    border: 1px solid var(--cl-border-soft);
    border-left: 3px solid var(--cl-mist);
    border-radius: var(--cl-radius-sm);
    background: linear-gradient(90deg, rgba(195, 192, 170, 0.38), rgba(239, 234, 218, 0.36));
}

.drawer-content :is(h2, h3, h4),
.popup :is(h2, h3, h4) {
    color: var(--cl-deep);
    font-family: var(--cl-font-serif);
    font-weight: 400;
    letter-spacing: 0.08em;
}

.dragClose,
.floating_panel_close,
.popup-button-close,
#logprobsViewerClose {
    color: var(--cl-danger);
    border: 1px solid rgba(155, 98, 93, 0.42);
    border-radius: var(--cl-radius-sm);
    background: rgba(248, 245, 235, 0.96);
}

.right_menu_button,
.inline-drawer-icon,
.logprobs_panel_control_button {
    color: var(--cl-mid);
    border-radius: var(--cl-radius-sm);
    opacity: 0.92;
    filter: none;
    text-shadow: none;
}

/* SOURCE: src/windows/text-generation.css */
/* ================================================================
   W04 文本补全参数
   ================================================================ */
#left-nav-panel :is(.range-block, .range-block-range, .range-block-range-and-counter, .settingsSectionWrap) {
    margin-block: 5px;
    border-color: var(--cl-border-soft);
    border-radius: 9px;
    background-color: rgba(239, 234, 218, 0.58);
}

#textgenerationwebui_api-presets,
#textgenerationwebui_api-settings {
