/* SOURCE: src/windows/mobile.css */
/* ================================================================
   W14 手机端
   宽度、抽屉开关与滚动继续由官方 mobile-styles.css 控制。
   ================================================================ */
@media (max-width: 700px) {
    :root {
        --cl-glass-blur: 9px;
    }

    body {
        background-position: center top;
        background-size: auto 100%;
    }

    #chat .mes:not([is_system="true"]) > .mes_block::before {
        height: 112px;
        padding: 11px 8px 0;
        background:
            linear-gradient(to bottom, rgba(248, 245, 235, 0.99) 0 36px, rgba(248, 245, 235, 0.06) 36px 100%),
            var(--cl-botanical-paper) center 34% / cover no-repeat,
            var(--cl-paper-strong);
        font-size: calc(var(--mainFontSize, 15px) * 0.57);
        letter-spacing: 0.09em;
    }

    #chat .mes:not([is_system="true"]) {
        width: 100%;
        margin-block: 8px 12px;
        padding: 0 10px;
    }

    #chat .mes:not([is_system="true"])[mesid]::after {
        top: 11px;
        left: 18px;
        font-size: calc(var(--mainFontSize, 15px) * 0.57);
    }

    #chat :is(.mes_text, .mes_reasoning) {
        font-size: var(--mainFontSize, 15px);
        line-height: 1.80;
    }

    #chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning) {
        padding: 11px 12px 17px;
    }

    #chat .mes[is_user="false"] :is(.mes_text, .mes_reasoning) {
        width: 100%;
        max-width: 100%;
        margin-inline: auto;
        padding: 12px 12px 22px;
    }

    #chat .ch_name {
        padding-inline: 11px;
    }

    #left-nav-panel .drawer-content {
        border-color: var(--cl-border);
    }

    #openai_api-presets {
        padding: 6px;
        color: var(--cl-text);
        border: 1px solid var(--cl-border);
        border-radius: var(--cl-radius-md);
        background-color: var(--cl-paper-strong);
    }

    #left-nav-panel #openai_api-presets #settings_preset_openai {
        color: var(--cl-ink);
        border: 1px solid var(--cl-border);
        background-color: var(--cl-paper-strong);
        opacity: 1;
        filter: none;
        text-shadow: none;
    }

    #send_form {
        border-radius: var(--cl-radius-md);
    }

    #send_textarea {
        padding: 9px 10px;
        font-size: var(--mainFontSize, 15px);
    }

    .drawer-content {
        border-radius: 0 0 var(--cl-radius-lg) var(--cl-radius-lg);
    }

    body #toast-container > .toast {
        max-width: calc(100% - 20px);
    }
}

@media (prefers-reduced-motion: reduce) {
    :is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu) {
        scroll-behavior: auto;
    }
}

