}

/* SOURCE: src/variants/dark.css */
/* ================================================================
   春来（暗色版）· 夜纸重构
   原版构图的暗色对应版：宋体正文、低饱和纸景、明确表面层级。
   ================================================================ */
:root {
    /* 原版 deep / mid / mist 的语义保持不变：由深到浅。 */
    --cl-deep: #1c2d2a;
    --cl-mid: #3b4a38;
    --cl-mist: #858d78;
    --cl-olive: #6b765c;

    /* 暗色专用表面，不再拿高亮色冒充 deep。 */
    --cl-surface-0: #0e1719;
    --cl-surface-1: #15211f;
    --cl-surface-2: #1c2d2a;
    --cl-surface-3: #26362f;
    --cl-surface-raised: #304137;
    --cl-settings-surface: #1b2424;
    --cl-settings-card: #252d2a;
    --cl-settings-raised: #303733;
    --cl-paper: var(--cl-surface-0);
    --cl-paper-strong: var(--cl-surface-2);
    --cl-paper-soft: var(--cl-surface-3);

    /* 长文使用柔和米苔色；近白只留给标题与焦点。 */
    --cl-ink: #dedcc7;
    --cl-text: #c9c9b4;
    --cl-muted: #959b88;
    --cl-text-disabled: #747b6d;
    --cl-accent: #9da28b;
    --cl-accent-strong: #baba9e;
    --cl-on-accent: #111b19;

    --cl-danger: #b98579;
    --cl-danger-surface: #4a302e;
    --cl-warning: #bea56f;
    --cl-warning-surface: #473d29;
    --cl-success: #8fa68f;
    --cl-success-surface: #263b31;

    --cl-border: rgba(157, 162, 139, 0.28);
    --cl-border-soft: rgba(157, 162, 139, 0.15);
    --cl-rule: rgba(133, 141, 120, 0.22);
    --cl-focus: #baba9e;
    --cl-shadow: 0 18px 48px rgba(5, 12, 12, 0.44);
    --cl-shadow-soft: 0 8px 24px rgba(5, 12, 12, 0.30);

    --cl-glass-chat: rgba(14, 23, 25, 0.64);
    --cl-glass-chrome: var(--cl-surface-1);
    --cl-glass-input: var(--cl-surface-2);
    --cl-glass-saturation: 102%;

    --cl-quote-bg: rgba(38, 54, 47, 0.72);
    --cl-quote-text: #b8bba8;
    --cl-quote-border: transparent;
    --cl-quote-inline-bg: rgba(107, 118, 92, 0.18);
    --cl-quote-inline-text: #c7c8b6;

    /* 暗色正文与设置界面均恢复宋体；图标继续使用各自原生图标字体。 */
    --cl-font-serif: "Source Han Serif SC", "Noto Serif CJK SC", "Songti SC", SimSun, serif;
    --cl-font-label: "Source Han Serif SC", "Noto Serif CJK SC", "Songti SC", SimSun, serif;
    --cl-font-ui: var(--cl-font-serif);
    --mainFontFamily: var(--cl-font-serif);

    --cl-botanical-paper: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/f633f5d7c0470a8dc5b73d33198178615975c6c3/assets/chunlai/chunlai-botanical-night-v5.png");
}

body {
    color: var(--cl-text);
    background-color: var(--cl-surface-0);
    background-image: var(--cl-botanical-paper);
    background-blend-mode: normal;
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
    font-family: var(--cl-font-serif);
}

body :focus-visible {
    outline: 3px solid var(--cl-focus);
    outline-offset: 2px;
}

body ::selection {
    color: var(--cl-on-accent);
    background: var(--cl-accent-strong);
}

#sheld {
    border-inline: 0;
    background: rgba(14, 23, 25, 0.18);
    box-shadow: 0 0 56px rgba(5, 12, 12, 0.36);
}

/* W01 主聊天：背景负责氛围，正文纸页负责阅读。 */
#chat {
    color: var(--cl-text);
    border: 0;
    background-color: var(--cl-glass-chat);
    background-image: none;
    background-repeat: no-repeat;
    box-shadow:
        inset 20px 0 48px rgba(5, 12, 12, 0.12),
        inset -20px 0 48px rgba(5, 12, 12, 0.12);
}

#chat .mes:not([is_system="true"]) > .mes_block {
    color: var(--cl-text);
    border: 0;
    border-radius: 12px;
    background: linear-gradient(145deg, rgba(28, 45, 42, 0.97), rgba(21, 33, 31, 0.98));
    box-shadow: 0 14px 34px rgba(5, 12, 12, 0.30);
}

#chat .mes:not([is_system="true"]) > .mes_block::before {
    color: var(--cl-ink);
    border: 0;
    border-radius: 12px 12px 0 0;
    background:
        linear-gradient(to bottom, rgba(14, 23, 25, 0.08), rgba(14, 23, 25, 0.32)),
        var(--cl-botanical-paper) center 26% / cover no-repeat,
        var(--cl-surface-2);
    box-shadow: inset 0 -30px 48px rgba(5, 12, 12, 0.30);
    text-shadow: 0 2px 10px rgba(5, 12, 12, 0.64);
}

#chat .ch_name {
    color: var(--cl-ink);
    border: 0;
    background: linear-gradient(90deg, rgba(38, 54, 47, 0.96), rgba(21, 33, 31, 0.72) 70%, transparent 96%);
}

#chat :is(.name_text, .mes:not([is_system="true"])[mesid]::after) {
    color: var(--cl-ink);
}

#chat .timestamp,
#chat :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    color: var(--cl-muted);
}

#chat :is(.mes_text, .mes_reasoning) {
    color: var(--cl-text);
    font-family: var(--cl-font-serif);
    text-shadow: none;
}

#chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning) {
    color: #d1d0ba;
}

#chat .mes_reasoning_header {
    color: var(--cl-text);
    border: 0;
    background: var(--cl-surface-3);
    box-shadow: inset 6px 0 0 var(--cl-olive);
}

#chat .mes_reasoning_header:hover,
#chat .mes_reasoning_details[open] .mes_reasoning_header {
    color: var(--cl-ink);
    border: 0;
    background: var(--cl-surface-raised);
}

#chat .mes_reasoning_arrow {
    color: var(--cl-mist);
}

#chat :is(.mes_text, .mes_reasoning) :is(q, .quote) {
    color: var(--cl-quote-inline-text);
    background-color: rgba(107, 118, 92, 0.08);
    background-image: linear-gradient(
        90deg,
        rgba(107, 118, 92, 0.34) 0%,
        rgba(107, 118, 92, 0.17) 48%,
        rgba(107, 118, 92, 0.06) 100%
    );
    box-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
    color: var(--cl-quote-text);
    border: 0;
    border-radius: 8px;
    background: linear-gradient(
        90deg,
        rgba(107, 118, 92, 0.34) 0%,
        rgba(67, 82, 65, 0.20) 44%,
        rgba(38, 54, 47, 0.08) 100%
    );
    box-shadow: 0 6px 16px rgba(5, 12, 12, 0.14);
}

#chat :is(.mes_text, .mes_reasoning) hr {
    height: 6px;
    margin-block: 1.5em;
    border: 0;
    border-radius: 999px;
    background: linear-gradient(90deg, transparent, rgba(133, 141, 120, 0.42) 32%, rgba(107, 118, 92, 0.50) 68%, transparent);
}

#chat :is(.mes_text, .mes_reasoning) :is(pre, code.hljs) {
    color: var(--cl-text);
    border: 0;
    background: var(--cl-surface-1);
}

#chat :is(.mes_text, .mes_reasoning) pre {
    border-radius: 8px;
    box-shadow: inset 6px 0 0 var(--cl-olive), 0 8px 20px rgba(5, 12, 12, 0.22);
}

#chat :is(.mes_text, .mes_reasoning) code:not(.hljs) {
    color: var(--cl-on-accent);
    background: var(--cl-accent);
}

#chat .hljs-comment,
#chat .hljs-quote {
    color: var(--cl-muted);
}

#chat :is(.hljs-keyword, .hljs-selector-tag, .hljs-built_in) {
    color: #b8b49a;
}

#chat :is(.hljs-string, .hljs-title, .hljs-section, .hljs-attribute) {
    color: #9fb09d;
}

#chat :is(.hljs-number, .hljs-literal, .hljs-symbol, .hljs-bullet) {
    color: #c0a986;
}

#chat :is(.reasoning_edit_textarea, .edit_textarea) {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-surface-1);
    box-shadow: inset 0 0 0 2px var(--cl-border-soft);
}

#chat :is(.reasoning_edit_textarea, .edit_textarea):focus {
    box-shadow: inset 0 0 0 3px var(--cl-focus);
}

#chat .mes_edit_buttons {
    filter: none;
    box-shadow: none;
}

#chat .mes_edit_buttons .menu_button {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-surface-3);
    opacity: 1;
    filter: none;
    box-shadow: none;
}

#chat .mes_edit_buttons .menu_button:hover {
    color: var(--cl-on-accent);
    background-color: var(--cl-accent);
}

#chat .mes_edit_done.menu_button {
    color: var(--cl-on-accent);
    background-color: var(--cl-accent-strong);
}

#chat .mes_edit_cancel.menu_button {
    color: #ead8d2;
    background-color: var(--cl-danger-surface);
}

#chat .mes[is_system="true"] {
    color: var(--cl-text);
    border: 0;
    background: rgba(28, 45, 42, 0.94);
    box-shadow: inset 6px 0 0 var(--cl-olive);
}

/* W02 顶栏：最深表面，图标不抢正文。 */
#top-bar {
    color: var(--cl-text);
    border: 0;
    background: var(--cl-surface-0);
    box-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable) {
    color: var(--cl-mist);
    opacity: 0.88;
    filter: none;
    text-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable):hover,
#top-settings-holder .openIcon {
    color: var(--cl-accent-strong);
    opacity: 1;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable)::after {
    content: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable):hover::after,
#top-settings-holder .openIcon::after {
    background: transparent;
}

/* W03 输入区：与顶栏错开一级，不做亮边框。 */
#send_form {
    color: var(--cl-text);
    border: 0;
    background: var(--cl-surface-2);
    box-shadow: 0 12px 30px rgba(5, 12, 12, 0.30);
}

#send_form::before,
#send_form::after {
    width: 24px;
    height: 24px;
    border: 0;
    border-radius: 8px;
    background: rgba(157, 162, 139, 0.13);
}

#send_textarea {
    color: var(--cl-text);
    border-color: transparent;
    background: var(--cl-surface-0);
    box-shadow: inset 0 0 0 2px rgba(157, 162, 139, 0.13);
}

#send_textarea:focus {
    box-shadow: inset 0 0 0 3px var(--cl-focus);
}

#send_textarea::placeholder {
    color: var(--cl-muted);
}

#leftSendForm > div,
#rightSendForm > div,
#options_button,
#extensionsMenuButton,
#send_but.fa-paper-plane {
    color: var(--cl-mist);
    opacity: 0.88;
    filter: none;
    text-shadow: none;
}

#leftSendForm > div:hover,
#rightSendForm > div:hover,
#options_button:hover,
#extensionsMenuButton:hover,
#send_but.fa-paper-plane:hover {
    color: var(--cl-accent-strong);
    opacity: 1;
}

#leftSendForm > div:hover::after,
#rightSendForm > div:hover::after,
#leftSendForm > div:focus-visible::after,
#rightSendForm > div:focus-visible::after {
    height: 5px;
    border-radius: 999px;
    background: var(--cl-olive);
}

/* W04-W12 功能窗口：统一宋体，以低饱和松炭色区分层级。 */
.drawer-content,
.popup,
#options,
#extensionsMenu,
.select2-dropdown {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-settings-surface);
    background-image: none;
    font-family: var(--cl-font-ui);
    box-shadow: var(--cl-shadow);
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(h2, h3, h4),
.inline-drawer-header,
.standoutHeader {
    color: var(--cl-ink);
    font-family: var(--cl-font-label);
}

:is(.drawer-content, .popup, #options, #extensionsMenu)
    :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select),
.select2-container--default .select2-selection {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-surface-0);
    box-shadow: inset 0 0 0 2px var(--cl-border-soft);
}

:is(.drawer-content, .popup, #options, #extensionsMenu)
    :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select):focus,
.select2-container--default.select2-container--focus .select2-selection {
    box-shadow: inset 0 0 0 3px var(--cl-focus);
}

select option,
select optgroup,
select option:not(:checked) {
    color: var(--cl-text) !important;
    background-color: var(--cl-settings-surface) !important;
}

select option:checked {
    color: var(--cl-on-accent) !important;
    background-color: var(--cl-accent) !important;
}

.select2-container--default .select2-results__option {
    color: var(--cl-text);
    background-color: var(--cl-settings-surface);
}

.select2-container--default .select2-results__option--highlighted,
.select2-container--default .select2-results__option[aria-selected="true"] {
    color: var(--cl-on-accent);
    background-color: var(--cl-accent);
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button) {
    color: var(--cl-text);
    border-color: transparent;
    background: var(--cl-settings-card);
    opacity: 1;
    filter: none;
    box-shadow: none;
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button):hover,
:is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button).active {
    color: var(--cl-on-accent);
    background: var(--cl-accent);
    filter: none;
}

:is(.drawer-content, .popup, #options, #extensionsMenu)
    :is(input:not([type="range"]), textarea, select, button, .menu_button):disabled,
:is(.drawer-content, .popup, #options, #extensionsMenu) .disabled {
    color: var(--cl-text-disabled);
    border-color: transparent;
    background-color: #282d29;
    opacity: 0.78;
    filter: none;
    box-shadow: none;
}

.inline-drawer-header,
.standoutHeader {
    border: 0;
    background: var(--cl-settings-card);
    box-shadow: none;
}

.dragClose,
.floating_panel_close,
.popup-button-close,
#logprobsViewerClose {
    color: #ead8d2;
    border: 0;
    background: var(--cl-danger-surface);
    box-shadow: none;
}

#rm_api_block :is(.api_button, .menu_button) {
    color: var(--cl-text);
    border-color: transparent;
    background: var(--cl-settings-card);
    box-shadow: none;
}

#left-nav-panel :is(.range-block, .range-block-range, .range-block-range-and-counter, .settingsSectionWrap),
#user-settings-block :is(.settingsSectionWrap, .range-block, fieldset),
#WorldInfo :is(.world_entry, .wi-card, .settingsSectionWrap),
#AdvancedFormatting .inline-drawer-content {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-settings-card);
    box-shadow: none;
}

#AdvancedFormatting,
#WorldInfo,
#user-settings-block,
#Backgrounds,
#rm_extensions_block,
#PersonaManagement,
#right-nav-panel {
    color: var(--cl-text);
    background-color: var(--cl-settings-surface);
}

#AdvancedFormatting :is(.inline-drawer-header, .standoutHeader),
#WorldInfo .world_entry .inline-drawer-header,
#user-settings-block h4,
#rm_extensions_block #extensions_settings .inline-drawer-toggle.inline-drawer-header,
#rm_extensions_block #extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#rm_extensions_block .standoutHeader.inline-drawer-header,
#rm_extensions_block .standoutHeader,
#rm_extensions_block .inline-drawer-header {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-settings-card);
    background-image: none;
    box-shadow: none;
}

/* 全局导入/导出是可点击操作，不与真实禁用模板共用灰态。 */
#AdvancedFormatting :is(#af_master_import, #af_master_export).menu_button:not(.disabled):not([disabled]) {
    color: #f4f0dd;
    border-color: transparent;
    background: #4b5a47;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#AdvancedFormatting :is(#af_master_import, #af_master_export).menu_button:not(.disabled):not([disabled]):hover {
    color: var(--cl-on-accent);
    border-color: transparent;
    background: var(--cl-accent-strong);
    opacity: 1;
    filter: none;
}

#AdvancedFormatting :is(#af_master_import, #af_master_export).menu_button:not(.disabled):not([disabled]):focus-visible {
    color: var(--cl-on-accent);
    border-color: transparent;
    background: var(--cl-accent);
    outline: 3px solid var(--cl-focus);
    outline-offset: 2px;
    opacity: 1;
    filter: none;
}

#AdvancedFormatting :is(#af_master_import, #af_master_export).menu_button:not(.disabled):not([disabled]):active {
    color: var(--cl-on-accent);
    border-color: transparent;
    background: var(--cl-mist);
    opacity: 1;
    filter: none;
}

#AdvancedFormatting :is(#af_master_import, #af_master_export).menu_button:is(.disabled, [disabled]) {
    color: var(--cl-text-disabled);
    border-color: transparent;
    background: #282d29;
    opacity: 0.78;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#rm_extensions_block :is(.standoutHeader, .inline-drawer-header):hover {
    color: var(--cl-ink);
    border-color: transparent;
    background-color: var(--cl-settings-raised);
    background-image: none;
    filter: none;
}

#rm_extensions_block .inline-drawer-icon {
    color: var(--cl-mist);
    background: transparent;
    opacity: 1;
    filter: none;
}

#AdvancedFormatting :is(textarea, input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), select),
#WorldInfo :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select, .select2-selection) {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-surface-0);
    box-shadow: inset 0 0 0 2px var(--cl-border-soft);
}

#completion_prompt_manager,
#completion_prompt_manager #completion_prompt_manager_list {
    color: var(--cl-text);
    background-color: var(--cl-settings-surface);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-settings-card);
    box-shadow: none;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover {
    color: var(--cl-ink);
    border-color: transparent;
    background-color: var(--cl-settings-raised);
}

#completion_prompt_manager :is(.prompt-manager-detach-action, .prompt-manager-edit-action, .prompt-manager-toggle-action) {
    color: var(--cl-mist);
    opacity: 1;
    filter: none;
    text-shadow: none;
    box-shadow: none;
}

#completion_prompt_manager :is(.prompt-manager-detach-action, .prompt-manager-edit-action, .prompt-manager-toggle-action):hover {
    color: var(--cl-accent-strong);
}

#AdvancedFormatting :is(textarea, input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), select):disabled,
#WorldInfo :is(input, textarea, select):disabled,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt[data-pm-enabled="false"],
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.disabled,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    color: var(--cl-text-disabled);
    background-color: #282d29;
    opacity: 0.78;
    filter: none;
}

#left-nav-panel #openai_settings .toggle-description code,
#AdvancedFormatting code,
#completion_prompt_manager code {
    color: var(--cl-on-accent);
    border: 0;
    background: var(--cl-accent);
}

#right-nav-panel :is(.character_select, .group_select, .avatar-container, .character_select_container),
#PersonaManagement .avatar-container,
#Backgrounds :is(.bg_example, .background_select),
#rm_extensions_block :is(.extension_container, .extensions_block) {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-settings-card);
    box-shadow: 0 7px 18px rgba(5, 12, 12, 0.20);
}

#right-nav-panel :is(.character_select, .group_select, .avatar-container):hover,
#Backgrounds :is(.bg_example, .background_select):hover {
    color: var(--cl-ink);
    border-color: transparent;
    background-color: var(--cl-settings-raised);
}

#right-nav-panel :is(#tagList, .tags, .tags_inline) {
    opacity: 1;
    filter: none;
}

#right-nav-panel :is(#tagList, .tags, .tags_inline) .tag {
    color: var(--cl-on-accent) !important;
    border-color: transparent !important;
    background-color: var(--cl-accent) !important;
    opacity: 1;
    filter: none;
    box-shadow: none;
}

#right-nav-panel :is(#tagList, .tags, .tags_inline) .tag:hover,
#right-nav-panel :is(#tagList, .tags, .tags_inline) .tag.selected {
    background-color: var(--cl-accent-strong) !important;
}

#right-nav-panel .avatar img,
#PersonaManagement .avatar img {
    border: 0;
    box-shadow: 0 0 0 4px rgba(157, 162, 139, 0.18);
}

/* 表单控制：填充态区分，不依赖细边线。 */
:is(.drawer-content, .popup, #options, #extensionsMenu) input[type="checkbox"],
:is(.drawer-content, .popup, #options, #extensionsMenu) input[type="radio"] {
    color: var(--cl-on-accent);
    border: 0;
    background-color: var(--cl-surface-0);
    box-shadow: inset 0 0 0 2px var(--cl-border);
}

:is(.drawer-content, .popup, #options, #extensionsMenu) input[type="checkbox"]:checked,
:is(.drawer-content, .popup, #options, #extensionsMenu) input[type="radio"]:checked {
    background-color: var(--cl-accent);
    box-shadow: none;
}

:is(.drawer-content, .popup, #options, #extensionsMenu) input[type="checkbox"]::before {
    color: var(--cl-on-accent);
}

:is(.drawer-content, .popup, #options, #extensionsMenu) input[type="range"] {
    accent-color: var(--cl-accent);
}

/* W13 弹窗、菜单与通知。 */
:is(.popup, .popup-content, .popup-body, .popper-modal),
body #toast-container > .toast,
#options,
#extensionsMenu,
:is(.list-group, .options-content, .dropdown-content, .select2-dropdown) {
    color: var(--cl-text);
    border-color: transparent;
    background-color: var(--cl-surface-2);
    background-image: none;
    box-shadow: var(--cl-shadow-soft);
}

body #toast-container > .toast {
    border-left-width: 0;
    box-shadow: inset 7px 0 0 var(--cl-olive), var(--cl-shadow-soft);
}

body #toast-container > .toast-success {
    box-shadow: inset 7px 0 0 var(--cl-success), var(--cl-shadow-soft);
}

body #toast-container > .toast-warning {
    box-shadow: inset 7px 0 0 var(--cl-warning), var(--cl-shadow-soft);
}

body #toast-container > .toast-error {
    box-shadow: inset 7px 0 0 var(--cl-danger), var(--cl-shadow-soft);
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    #chat {
        background-color: rgba(21, 33, 31, 0.96);
    }
}

@media (max-width: 700px) {
    body {
        background-position: center top;
        background-size: cover;
    }

    #chat .mes:not([is_system="true"]) > .mes_block::before {
        background:
            linear-gradient(to bottom, rgba(14, 23, 25, 0.06), rgba(14, 23, 25, 0.30)),
            var(--cl-botanical-paper) center 28% / cover no-repeat,
            var(--cl-surface-2);
    }
}
